// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.gc;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GcDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        TransactionBatch batch = new TransactionBatch();
        batch.process(rajesh, priya, new BigDecimal("50000"));

        // After process(), the temporary objects it created are unreachable
        // from any root, so they are eligible for garbage collection.
        log.info(() -> "Temporary batch objects now unreachable → GC-eligible");

        // Cyclic references: a→b and b→a, but neither reachable from a root.
        Node a = new Node("A");
        Node b = new Node("B");
        a.link(b);
        b.link(a);          // cycle created
        a = null;           // drop both roots
        b = null;
        // The cycle is still collectible because reachability, not ref-count, is used.
        log.info(() -> "Cycle A<->B has no root → still GC-eligible (reachability wins)");

        System.gc();        // a HINT only; JVM decides when to actually collect
        log.info(() -> "Requested GC hint; collection timing is JVM-decided");
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in TransactionBatch.java ───
class TransactionBatch {
    private static final Logger log = Logger.getLogger("BankLog");

    void process(Account from, Account to, BigDecimal amount) {
        // 'receipt' is a temporary object, local to this method only.
        String receipt = "RCPT-" + from.getHolderName() + "-" + amount;
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "Processed " + receipt + " → " + from.getHolderName()
                + " now Rs." + from.getBalance());
        // On return, 'receipt' is no longer reachable → eligible for GC.
    }
}

// ─── Would be in Node.java (demonstrates collectible cycles) ───
class Node {
    private final String id;
    private Node other;
    Node(String id) { this.id = id; }
    void link(Node n) { this.other = n; }
    String getId() { return id; }
}
